#include <string>

class Solution {
public:
    int sumOfDecodedNumbers(std::string s) {
        long long MOD = 1000000007;
        int n = s.size();
        if (n == 0 || s[0] == '0') return 0;

        long long w0 = 1, s0 = 0;
        long long w1 = 1, s1 = s[0] - '0';

        for (int i = 1; i < n; ++i) {
            long long w_cur = 0, s_cur = 0;
            int d1 = s[i] - '0';
            int d2 = (s[i - 1] - '0') * 10 + d1;

            if (d1 >= 1 && d1 <= 9) {
                w_cur = (w_cur + w1) % MOD;
                s_cur = (s_cur + s1 + w1 * d1) % MOD;
            }
            if (d2 >= 10 && d2 <= 26) {
                w_cur = (w_cur + w0) % MOD;
                s_cur = (s_cur + s0 + w0 * d2) % MOD;
            }

            w0 = w1; s0 = s1;
            w1 = w_cur; s1 = s_cur;
        }
        return s1 % MOD;
    }
};

class Solution {
    public int sumOfDecodedNumbers(String s) {
        long MOD = 1000000007L;
        int n = s.length();
        if (n == 0 || s.charAt(0) == '0') return 0;

        long w0 = 1, s0 = 0;
        long w1 = 1, s1 = s.charAt(0) - '0';

        for (int i = 1; i < n; i++) {
            long wCur = 0, sCur = 0;
            int d1 = s.charAt(i) - '0';
            int d2 = (s.charAt(i - 1) - '0') * 10 + d1;

            if (d1 >= 1 && d1 <= 9) {
                wCur = (wCur + w1) % MOD;
                sCur = (sCur + s1 + w1 * d1) % MOD;
            }
            if (d2 >= 10 && d2 <= 26) {
                wCur = (wCur + w0) % MOD;
                sCur = (sCur + s0 + w0 * d2) % MOD;
            }

            w0 = w1; s0 = s1;
            w1 = wCur; s1 = sCur;
        }
        return (int) (s1 % MOD);
    }
}

function sumOfDecodedNumbers(s) {
    const MOD = 1000000007n;
    const n = s.length;
    if (n === 0 || s[0] === '0') return 0;

    let w0 = 1n, s0 = 0n;
    let w1 = 1n, s1 = BigInt(s[0]);

    for (let i = 1; i < n; i++) {
        let wCur = 0n, sCur = 0n;
        const d1 = BigInt(s[i]);
        const d2 = BigInt(s.slice(i - 1, i + 1));

        if (d1 >= 1n && d1 <= 9n) {
            wCur = (wCur + w1) % MOD;
            sCur = (sCur + s1 + w1 * d1) % MOD;
        }
        if (d2 >= 10n && d2 <= 26n) {
            wCur = (wCur + w0) % MOD;
            sCur = (sCur + s0 + w0 * d2) % MOD;
        }

        w0 = w1; s0 = s1;
        w1 = wCur; s1 = sCur;
    }
    return Number(s1 % MOD);
}
